module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        LEFT,
        RIGHT,
        FALL_L,
        FALL_R,
        DIG_L,
        DIG_R,
        SPLAT
    } state_t;

    state_t state, next_state;
    logic [4:0] fall_cnt;  // up to 21 saturate

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= LEFT;
            fall_cnt <= 5'd0;
        end else begin
            state <= next_state;
            case (state)
                FALL_L, FALL_R: begin
                    if (ground) begin
                        fall_cnt <= 5'd0;
                    end else begin
                        if (fall_cnt < 5'd21)
                            fall_cnt <= fall_cnt + 5'd1;
                        else
                            fall_cnt <= fall_cnt;
                    end
                end
                default: fall_cnt <= 5'd0;
            endcase
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state;
        case (state)
            LEFT: begin
                if (!ground)
                    next_state = FALL_L;
                else if (dig)
                    next_state = DIG_L;
                else if (bump_left)
                    next_state = RIGHT;
                else
                    next_state = LEFT;
            end
            RIGHT: begin
                if (!ground)
                    next_state = FALL_R;
                else if (dig)
                    next_state = DIG_R;
                else if (bump_right)
                    next_state = LEFT;
                else
                    next_state = RIGHT;
            end
            FALL_L: begin
                if (ground) begin
                    if (fall_cnt > 5'd20)
                        next_state = SPLAT;
                    else
                        next_state = LEFT;
                end else begin
                    next_state = FALL_L;
                end
            end
            FALL_R: begin
                if (ground) begin
                    if (fall_cnt > 5'd20)
                        next_state = SPLAT;
                    else
                        next_state = RIGHT;
                end else begin
                    next_state = FALL_R;
                end
            end
            DIG_L: begin
                if (!ground)
                    next_state = FALL_L;
                else
                    next_state = DIG_L;
            end
            DIG_R: begin
                if (!ground)
                    next_state = FALL_R;
                else
                    next_state = DIG_R;
            end
            SPLAT: begin
                next_state = SPLAT;
            end
            default: next_state = LEFT;
        endcase
    end

    // Outputs
    assign walk_left  = (state == LEFT);
    assign walk_right = (state == RIGHT);
    assign aaah       = (state == FALL_L) || (state == FALL_R);
    assign digging    = (state == DIG_L) || (state == DIG_R);

endmodule
```

